('20260903195039160','APP_CREDIT_REPORT_INFO','最新一期征信情况-企业','LIST',NULL,NULL,NULL,'N',NULL,'calc',NULL,NULL,'2095329761296400386',NULL,'Public',NULL,'Auto','征信情况','Public','1.0','3',NULL,NULL,NULL,'APP_CREDIT_REPORT_INFO',NULL,NULL,NULL,NULL,'NULL::character varying','APP_CREDIT_REPORT_INFO','bosz-dev-local-0001',NULL,'Sql','{"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.ID,\n    i.REPORTNO,\n    i.CUSTOMERID,\n    i.CUSTOMERNAME,\n    u.creditSum AS 授信金额,\n    i.QUERYTIME,\n    TO_CHAR(CURRENT_DATE, ''YYYY-MM-DD'') AS \"当前时间\",\n    CURRENT_DATE - CAST(i.QUERYTIME AS DATE) AS \"最新一期征信查询时间距当前时间天数\",\n    i.ZXREPORTNO,\n    i.EXPIREDATE,\n    i.OVERDUETOTAL,\n    i.ATTENTIONCREDITBAL,\n    i.BADCREDITBAL,\n    i.ATTENTIONGUARANTEEBAL,\n    i.BADGUARANTEEBAL,\n    i.GUARANTEEOVERDUETOTAL,\n    i.GUARANTEEATTENTIONBAL,\n    i.GUARANTEEBADBAL,\n    i.EXTENDDEBTBAL,\n    i.RESTRUCTUREDEBTBAL,\n    i.RENEWDEBTBAL,\n    i.TRANSFERDEBTBAL,\n    i.NEWOLDDEBTBAL,\n    i.NONBANKLIABTOTAL,\n    i.NONBANKHIGHRATELOAN,\n    i.INPUTTIME,\n    i.SUBJECTTYPE,\n    i.GUARANTORID,\n    i.GUARANTORNAME,\n    i.NONBANKGUARANTEEBAL,\n    i.WORKINGCAPITALLOANBAL,\n    i.WORKINGCAPITALLOAN1YBAL,\n    i.LOANBANKORGCOUNT,\n    i.GUARANTEEBANKORGCOUNT,\n    i.CREDITSHORTTERMDIFF,\n    i.CREDITLONGTERMDIFF,\n    i.CREDITDEBTDEVIATION,\n    i.GUARANTEENETASSET,\n    i.GUARANTEEBALANCEEXBANK,\n    i.SHORTTERMLOANORGCOUNT,\n    i.MIDLONGTERMLOANORGCOUNT,\n    i.REVOLVINGOVERDRAFTORGCOUNT,\n    i.DISCOUNTORGCOUNT,\n    i.BANKACCEPTANCEBILLORGCOUNT,\n    i.LETTEROFCREDITORGCOUNT,\n    i.BANKGUARANTEEORGCOUNT,\n    i.OTHERGUARANTEETRADEORGCOUNT,\n    i.SHORTTERMLOANBAL,\n    i.MIDLONGTERMLOANBAL,\n    i.REVOLVINGOVERDRAFTBAL,\n    i.DISCOUNTBAL,\n    i.BANKACCEPTANCEBILLBAL,\n    i.LETTEROFCREDITBAL,\n    i.BANKGUARANTEEBAL,\n    i.OTHERGUARANTEETRADEBAL\nFROM APP_CREDIT_REPORT_INFO i\nINNER JOIN APP_GUARANTOR_INFO g\n    ON i.ZXREPORTNO = g.ZXREPORTNOZX\nLEFT JOIN APP_CREDIT_USE_INFO u\n    ON i.REPORTNO = u.REPORTNO\n    AND i.CUSTOMERID = u.CUSTOMERID\n    AND i.CUSTOMERNAME = u.CUSTOMERNAME\n    AND u.reportno = :reportNo\n    AND u.customername = :entName\nWHERE g.reportno = :reportNo\n  AND g.customername = :entName\n  AND g.guarantorname = :guarantorName\n  AND i.reportno = :reportNo\n  AND i.customername = :entName","paramData":[{"id":"45b00f5a-ba9a-28b9-86eb-8cd38120e4e1","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"''RPT-202603-001''","relateIndex":null},{"id":"b362361f-6e31-fb0c-3b0d-c64b452b89ec","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"''苏州XX精密机械制造有限公司''","relateIndex":null},{"id":"fdf026be-ed28-ee8b-93cf-961245bb4dc2","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"''泰州公司''","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}',NULL,NULL,'admin',NULL,'2026-09-03 19:50:39','admin',NULL,'2026-09-07 09:32:38',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'','','','','',NULL),
